        for dx, dy in moves:
            nx, ny = sx + dx, sy + dy
            if not inb(nx, ny):
                continue
            v = cheb(ox, oy, nx, ny)
            if v > bestv:
                bestv = v
                best = [dx, dy]
        return best

    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if not inb(nx, ny):
            continue
        dr = min(cheb(nx, ny, rx, ry) for rx, ry in res)
        dpo = cheb(ox, oy, nx, ny)
        v = -dr * 100 + dpo
        if v > bestv:
            bestv = v
            best = [dx, dy]
    return best

